//! Bindings generated by `#[near]` must not be captured by user items in scope.
//!
//! Function and closure parameters, `let` bindings and match arms are identifier patterns, so a
//! plain generated name like `gas_weight` resolves to a same-named constant imported by the user
//! and becomes a constant pattern (E0005). Generated bindings use the reserved `__near_` prefix
//! instead.

#[allow(non_upper_case_globals, dead_code)]
mod consts {
    pub const amount: near_sdk::NearToken = near_sdk::NearToken::from_yoctonear(0);
    pub const static_gas: near_sdk::Gas = near_sdk::Gas::from_gas(0);
    pub const gas_weight: u64 = 0;
    pub const account_id: u64 = 0;
    pub const promise: u64 = 0;
    pub const p: u64 = 0;
}

#[allow(unused_imports)]
use consts::*;
use near_sdk::test_utils::VMContextBuilder;
use near_sdk::{Gas, NearToken, Promise, env, near, testing_env};

#[near(contract_state)]
#[derive(Default)]
pub struct Contract {
    n: u8,
}

#[near]
impl Contract {
    pub fn get(&self) -> u8 {
        self.n
    }
}

#[test]
fn ext_builder_ignores_user_consts() {
    testing_env!(VMContextBuilder::new().build());
    let _: Promise = Contract::ext(env::current_account_id())
        .with_attached_deposit(NearToken::from_yoctonear(1))
        .with_static_gas(Gas::from_tgas(5))
        .with_unused_gas_weight(1)
        .get();
    let _: Promise = Contract::ext_on(Promise::new(env::current_account_id())).get();
}

/// The `extern "C"` method wrappers only exist on wasm32, so check
/// `tests/test-contracts/macro_hygiene` for that target. It imports consts named like every binding
/// the wrappers generate.
#[test]
fn wasm32_method_wrappers_ignore_user_consts() {
    let status = std::process::Command::new("cargo")
        .args(["check", "--target", "wasm32-unknown-unknown", "--manifest-path"])
        .arg(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/test-contracts/macro_hygiene/Cargo.toml"))
        .status()
        .unwrap();
    assert!(status.success(), "checking the macro_hygiene test-contract for wasm32 failed");
}
